package lesson

import (
	"context"
	"fmt"
	"net/http"
)

type userIDKey struct{}

func WithUser(userID string, next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		ctx := context.WithValue(r.Context(), userIDKey{}, userID)
		next.ServeHTTP(w, r.WithContext(ctx))
	})
}

func UserID(ctx context.Context) (string, bool) {
	value, ok := ctx.Value(userIDKey{}).(string)
	return value, ok
}
func Profile(w http.ResponseWriter, r *http.Request) {
	userID, ok := UserID(r.Context())
	if !ok {
		http.Error(w, "missing user", 401)
		return
	}
	fmt.Fprint(w, userID)
}
```

**context_test.go**

```go
package lesson

import (
	"net/http"
	"net/http/httptest"
	"testing"
)

func TestUserContext(t *testing.T) {
	recorder := httptest.NewRecorder()
	WithUser("u-7", http.HandlerFunc(Profile)).ServeHTTP(recorder, httptest.NewRequest(http.MethodGet, "/profile", nil))
	if recorder.Code != 200 || recorder.Body.String() != "u-7" {
		t.Fatalf("status=%d body=%q", recorder.Code, recorder.Body.String())
	}
}
```

**Run it**

```bash
go test -race ./...
go vet ./...
```

The key type and getter stay private to the package contract; the endpoint receives the derived request rather than the original one.
